root=Path(__file__).parent
rows=[
dict(title='C-3PO (See-Threepio)',printed_title='C-3PO (See-Threepio)',type='Character',subtype='Droid',model='Protocol Droid',original_set='Premiere',set_icon=None,destiny='3',power='1',deploy='3',forfeit='4',icons=['Droid'],lore='Cybot Galactica 3PO human-cyborg relations droid. Fluent in over six million forms of communication. 112 years old. Has never been memory-wiped . . . as far as he knows.',game_text='Total power at same site is +2 for each of your droid/Rebel pairs present, including C-3PO. R2-D2 is forfeit +2 when present.'),
dict(title='Captain Han Solo',printed_title='Captain Han Solo',type='Character',subtype='Rebel',printed_label='Force-Attuned',original_set='Hoth',set_icon='Hoth',destiny='1',power='4',ability='3',deploy='4',forfeit='7',icons=['Rebel','Pilot','Warrior'],lore='Smuggler and scoundrel. His piloting abilities have become legend in the Rebellion. Intends to leave the Alliance to pay off Jabba the Hutt.',game_text="Deploys only on ''Falcon'', Hoth or Cloud City. Adds 3 to power of anything he pilots. When piloting ''Falcon'', adds one battle destiny and 2 to maneuver. Once during each battle, may use 2 Force to cancel one opponent’s destiny just drawn and cause a re-draw."),
dict(title='Chewbacca',printed_title='Chewbacca',type='Character',subtype='Rebel',type_display='[[Character]] ([[Alien]] / [[Rebel]])',original_set='A New Hope',set_icon='A New Hope',destiny='1',power='6',ability='2',deploy='4',forfeit='6',icons=['Alien','Rebel','Pilot','Warrior'],lore='Wookiee smuggler from Kashyyyk. Over 200 years old. Top-notch mechanic and pilot. Jabba has large bounty on this “walking carpet.” Friends call him Chewie . . . or Fuzzball.',game_text="Power +1 at same location as Han. Adds 2 to power of anything he pilots. When piloting ''Falcon'', also adds 1 to maneuver. Your vehicles, starships and droids at same site go to Used Pile (rather than Lost Pile) when they are ‘hit.’"),
dict(title='Han Solo',printed_title='Han Solo',type='Character',subtype='Rebel',printed_label='Force-Attuned',original_set='Premiere',set_icon=None,destiny='1',power='3',ability='3',deploy='3',forfeit='6',icons=['Rebel','Pilot','Warrior'],lore='Smuggler, gambler and “freelance law-bender.” Crafty Corellian pirate. Rebel hero. Owns ''Millennium Falcon''. Co-pilot Chewbacca promised him “life-debt.” Has bounty on head.',game_text="Once during battle, may use 1 Force to cancel and re-draw your just drawn destiny. Adds 2 to power of anything he pilots. When piloting ''Falcon'', also adds 2 to maneuver and may draw one battle destiny if not able to otherwise."),
dict(title='Leia Organa',printed_title='Leia Organa',type='Character',subtype='Rebel',printed_label='Force-Attuned',original_set='Premiere',set_icon=None,destiny='1',power='3',ability='3',deploy='3',forfeit='6',icons=['Rebel','Warrior'],lore='Strong-willed princess from Alderaan. Youngest Imperial Senator ever. Used diplomatic immunity to spy for Rebels. Led relief effort on Ralltiir. Natural leader.',game_text='Adds 1 to power of each Rebel present with her at a Death Star site. ‘Diplomatic’ immunity to attrition &lt; 2.'),
dict(title='Millennium Falcon',printed_title='Millennium Falcon',type='Starship',subtype='Starfighter',model='Modified Light Freighter',original_set='Premiere',set_icon=None,destiny='2',power='3',maneuver='4',hyperspeed='6',deploy='3',forfeit='7',icons=['Starship','Nav Computer','Scomp Link'],lore='Modified YT-1300 freighter. Owned by Lando Calrissian until won by Han in a sabacc game. 26.7 meters long. “She may not look like much, but she’s got it where it counts.”',game_text='May add 2 pilots and 2 passengers. Immune to attrition &lt; 5 if Han, Chewie or Lando piloting. Has ship-docking capability.'),
dict(title='Obi-Wan Kenobi',printed_title='Obi-Wan Kenobi',type='Character',subtype='Rebel',printed_label='Jedi Knight',original_set='Premiere',set_icon=None,destiny='1',power='5',ability='6',deploy='5',forfeit='9',icons=['Rebel','Warrior'],lore='Jedi Knight. Trained by Yoda. Friend of Bail Organa. General Kenobi became a hero of the Old Republic during the Clone Wars. Mentor of Anakin and Luke Skywalker.',game_text='When a battle was just initiated where present, may use 1 Force to choose one opponent’s character of ability = 1 present to move away (for free), or that character is lost. Immune to attrition &lt; 5.'),
dict(title='Princess Leia Organa',printed_title='Princess Leia Organa',type='Character',subtype='Rebel',printed_label='Force-Sensitive',original_set="Jabba's Palace",set_icon="Jabba's Palace",destiny='1',power='3',ability='4',deploy='*',forfeit='7',icons=['Rebel','Pilot','Warrior'],lore='Captured by Jabba. Princess Leia provided a distraction for his henchbeings. Waiting for the first chance to escape. Really made Jabba’s tail wiggle.',game_text='<nowiki>*</nowiki> Deploys free as an escorted captive of Jabba or a bounty hunter (you may not initiate battle there on same turn). While a captive, opponent’s unique (•) aliens at same site are forfeit -2. If released, retrieve 5 Force. Immune to attrition &lt; 3.'),
dict(title='R2-D2 (Artoo-Detoo)',printed_title='R2-D2 (Artoo-Detoo)',type='Character',subtype='Droid',model='Astromech Droid',original_set='A New Hope',set_icon='A New Hope',destiny='2 or 5',power='1',deploy='3',forfeit='4',icons=['Droid','Scomp Link'],lore='Feisty. Loyal. Heroic. Insecure. Rebel spy. Excels at trouble. Incorrigible counterpart of a mindless philosopher. Has picked up a slight flutter. A bit eccentric.',game_text='While aboard any starfighter, adds 2 to power, maneuver and hyperspeed (3 on Red 5). If at a Scomp link when opponent draws destiny of: 1-3, you may activate one Force; 4-6, you may draw top card from Reserve Deck.'),
dict(title='Son Of Skywalker',printed_title='Son Of Skywalker',type='Character',subtype='Rebel',printed_label='Force-Sensitive',original_set='Dagobah',set_icon='Dagobah',destiny='1',power='5',ability='5',deploy='5',forfeit='8',icons=['Rebel','Pilot','Warrior'],lore='Luke Skywalker. Son of Anakin. Seeker of Yoda. Levitator of rocks. Ignorer of advice. Incapable of impossible. Reckless is he.',game_text='Deploys only on Dagobah or Cloud City. Adds 2 to power of anything he pilots. Once per game, during your deploy phase, a lightsaber may deploy on Luke (for free) from Reserve Deck; reshuffle. Immune to attrition &lt; 4.')]
sources=json.loads((root/'batch2-source-manifest.json').read_bytes())
for row,src in zip(rows,sources):
    row.update(product='Reflections',language='English',side='Light',finish='Foil',uniqueness='Unique',copyright_year=1999,rarity='SR',article=src['article'],source_photo=src['local_file'],source_url=src['source_url'],source_sha256=src['sha256'],source_gallery=src['candidate']['source_html'],registry_key=src['candidate']['registry_key'],inspection='Full original physical foil and cropped reading sheets batch2-sheet-1 through 5; original image retained unchanged',status='manually inspected and independently transcribed',gemp_mapping='unverified: do not assert a playable ID')
    row['field_status']={k:'printed' for k in row if k in ['printed_title','type','subtype','type_display','model','destiny','power','ability','maneuver','hyperspeed','deploy','forfeit','icons','lore','game_text','printed_label','uniqueness','copyright_year']}
    row['field_status']['rarity']='catalogued: Complete Card List v4.0, Reflections foil section'
    if row['type']=='Character':row['rule_derived_landspeed']='1, standard character base; not printed'
    if row.get('subtype')=='Droid':row['field_status']['ability']='not applicable: no printed ability'
(root/'batch2-readings.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf8')
print('Ten second-batch physical foil readings recorded')
